@-moz-document domain("sudoku.com") {
/* Sudoku.com Dark
     
     Every locale is a path on this one host (/de, /jp, ...), so one
     domain() block covers the site. No custom properties: every colour
     is a literal in ref-game.css, so each surface needs its own rule.
     
     Tone map, preserving the site's elevation order:
     #fff            -> #1c2128  cards, popups, header, menus
     #f3f6fa #f1f4f8 -> #22272e  panels, hovers, active tabs
     #f0f4f9 #e4eaf1 -> #20252c  nested panels
     #eaeef4         -> #242b33  control fills (numpad, keys)
     #dce3ed         -> #2e3641  control hover
     #d2dae7         -> #39424f  control pressed
     #e0e8f7         -> #2d333b  borders
     #344861         -> #e6edf3  headings
     #6e7c8c         -> #a8b2bd  prominent muted text
     #94a3b7 #adb6c2 -> #8b949e  quieter muted text
     #325aaf         -> #7ea2ea  brand blue as INK
     #5a7bc0         -> #4a68ad  brand blue as BUTTON FILL
     
     Event panels (tournament orange, storybook cover, win gradient) are
     identity, not light leaks: keep the hue, drop one step.
     
     The 9x9 grid is a <canvas> whose colours live in a JS constant no
     CSS rule can reach, so the board is retoned by a filter chain. */

  :root {
    color-scheme: dark;
  }

  html,
  body {
    background-color: #14181d !important;
    color: #c4cdd6 !important;
  }

  /* Must not be !important: it only faces buttons the site never
     painted, and any author rule has to outrank it. */
  button,
  input[type="submit"],
  input[type="button"],
  input[type="reset"] {
    background-color: #22272e;
    color: #e6edf3;
    border-color: #2d333b;
  }

  /* THE BOARD
     
     hue-rotate(180) after invert() puts every hue back where the site
     drew it, so selected / same-value / conflict stay mutually distinct
     instead of collapsing to one grey. The smart-hint overlay canvas
     must stay on the same chain as the board or the layers stop lining
     up. */

  .game-wrapper .game canvas,
  #game canvas,
  #sh-canvas canvas {
    filter: invert(0.9) hue-rotate(180deg) saturate(1.28) brightness(1.2) !important;
  }

  /* The canvas keeps the site's white background: it is inside the
     filter, so #fff resolves to the empty-cell tone. Only the frame
     around it takes the page ground. */
  .game-wrapper {
    background-color: #14181d !important;
  }

  /* Must stay lighter than the scrim the site draws on light, or the
     board under it stops being legible. */
  .smart-hint {
    background-color: rgba(0, 0, 0, 0.5) !important;
  }

  /* HEADER */

  .header,
  .site-header,
  #masthead,
  .main-navigation {
    background-color: #0d1117 !important;
    border-color: #262c33 !important;
  }

  .header_menu > a,
  .header_menu > div.events,
  .nav-menu-item > a,
  .header_left a,
  .lang-menu_label,
  .lang-menu-label,
  .mode-menu-label {
    color: #c4cdd6 !important;
  }

  .header_menu > a.active:not(.dc):not(.tournament):not(.postcards):not(.storybook):not(.events),
  .header_menu > div.events.active:not(.dc):not(.tournament):not(.postcards):not(.storybook):not(.events),
  .nav-menu-item > a:not(.more-menu-open).active,
  .nav-menu-item > a:not(.more-menu-open).active span:not(.menu-notification),
  .header_mobile_dropdown a.active,
  .ref-mode-menu-item a.active span,
  .mode-menu-dropdown ul > li > a.active,
  .more-menu-dropdown li a.active {
    color: #9bc0ff !important;
  }

  .header_menu > a:not(.active):not(.dc):not(.tournament):not(.postcards):not(.storybook):not(.events):hover,
  .header_menu > div.events:not(.active):not(.dc):not(.tournament):not(.postcards):not(.storybook):not(.events):hover,
  .nav-menu-item > a:not(.active):hover,
  .header_mobile_dropdown a:not(.active):hover,
  .lang-menu_dropdown ul li a:hover,
  .lang-menu_label:hover,
  .lang-menu-label:hover,
  .mode-menu-label:hover,
  .ref-mode-menu-item a:not(.active):hover,
  .mode-menu-dropdown ul > li > a:not(.active):hover,
  .more-menu-dropdown li a:not(.active):hover,
  .difficulty-menu-dropdown a:hover,
  .lang-menu-dropdown a:hover,
  .mode-menu-dropdown a:hover {
    background-color: #22272e !important;
  }

  .header_menu > a:not(.active):not(.dc):not(.tournament):not(.postcards):not(.storybook):not(.events):active,
  .header_menu > div.events:not(.active):not(.dc):not(.tournament):not(.postcards):not(.storybook):not(.events):active,
  .nav-menu-item > a:not(.active):active,
  .ref-mode-menu-item a:active,
  .mode-menu-dropdown ul > li > a:not(.active):active,
  .header_mobile_dropdown a:not(.active):active {
    background-color: #2e3641 !important;
  }

  .header_menu > a.active:not(.dc):not(.tournament):not(.postcards):not(.storybook):not(.events),
  .nav-menu-item > a:not(.more-menu-open).active,
  .header_mobile_dropdown a.active,
  .mode-menu-dropdown ul > li > a.active,
  .more-menu-dropdown li a.active,
  .header .active.dc,
  .header .active.events,
  .header .active.postcards,
  .header .active.storybook,
  .header .active.tournament {
    background-color: #1c2128 !important;
  }

  /* An active chip drops its brand plate for ours, so its label goes
     from white to the active ink. */
  .header .active.dc,
  .header .active.events,
  .header .active.postcards,
  .header .active.storybook,
  .header .active.tournament,
  .header .active.dc span,
  .header .active.events span,
  .header .active.postcards span,
  .header .active.storybook span,
  .header .active.tournament span,
  .main-navigation a.active[class*="_header-link"],
  .main-navigation a.active[class*="_header-link"] span {
    color: #9bc0ff !important;
  }

  /* Burger bars and the header logo are drawn as boxes, not glyphs. */
  .header_burger > div,
  .header_burger:after,
  .header_burger:before {
    background-color: #c4cdd6 !important;
  }

  .header_mobile_dropdown,
  .header_mobile_dropdown:after,
  .header .events_dropdown,
  .header .events_dropdown:after,
  .events-menu,
  .lang-menu_dropdown,
  .difficulty-menu-dropdown,
  .lang-menu-dropdown,
  .mode-menu-dropdown,
  .more-menu-dropdown,
  .more-menu-dropdown:after,
  .main-navigation {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }

  /* Chips are brand plates: white label, until the chip is the active
     tab and takes our surface instead. */
  .header a.dc:not(.active),
  .header a.tournament:not(.active),
  .header a.postcards_header-link:not(.active),
  .header a.storybook_header-link:not(.active),
  .header a.ftc_header-link:not(.active),
  .header a.dc:not(.active) span,
  .header a.tournament:not(.active) span,
  .header a.postcards_header-link:not(.active) span,
  .header a.storybook_header-link:not(.active) span,
  .header a.ftc_header-link:not(.active) span,
  .main-navigation a.dc:not(.active),
  .main-navigation a.tournament:not(.active),
  .main-navigation a.postcards_header-link:not(.active),
  .main-navigation a.storybook_header-link:not(.active),
  .main-navigation a.ftc_header-link:not(.active),
  .main-navigation a.dc:not(.active) span,
  .main-navigation a.tournament:not(.active) span,
  .main-navigation a.postcards_header-link:not(.active) span,
  .main-navigation a.storybook_header-link:not(.active) span,
  .main-navigation a.ftc_header-link:not(.active) span {
    color: #ffffff !important;
  }

  /* The badge is its own light plate with deep blue numerals; the
     chip's white label must not reach inside it, so this is written to
     outrank the chip rule above. */
  .header a[class*="_header-link"] .postcards_header-icon > span,
  .header a[class*="_header-link"] .postcards_header-icon,
  .main-navigation a[class*="_header-link"] .postcards_header-icon > span,
  .main-navigation a[class*="_header-link"] .postcards_header-icon {
    color: #004caf !important;
  }

  .header a[class*="_header-link"] .postcards_header-icon.crown.place-1 > span,
  .header a[class*="_header-link"] .postcards_header-icon.crown.place-3 > span,
  .main-navigation a[class*="_header-link"] .postcards_header-icon.crown.place-1 > span,
  .main-navigation a[class*="_header-link"] .postcards_header-icon.crown.place-3 > span {
    color: #a92500 !important;
  }

  .header a[class*="_header-link"] .postcards_header-icon.crown.place-2 > span,
  .main-navigation a[class*="_header-link"] .postcards_header-icon.crown.place-2 > span {
    color: #3f617a !important;
  }

  .header .events_dropdown_title,
  .events-menu_title,
  .events-menu_menu > a,
  .events-menu_menu > div,
  .header .dc:not(.events) > span.info,
  .header .events:not(.events) > span.info,
  .header .postcards:not(.events) > span.info,
  .header .storybook:not(.events) > span.info,
  .header .tournament:not(.events) > span.info {
    color: #e6edf3 !important;
  }

  /* The white timer pill on a chip keeps its own plate so the
     countdown stays readable over it. */
  .header span.info,
  .header_menu span.info,
  .nav-menu-item span.info,
  .emoji_circle,
  .emoji_text,
  .inter-emoji_circle,
  .inter-emoji_text {
    background-color: #1c2128 !important;
    color: #e6edf3 !important;
  }

  .emoji_text,
  .inter-emoji_text {
    color: #9bc0ff !important;
  }

  .header .events_dropdown_item_button,
  .events-menu_item_button {
    background-color: #22272e !important;
    color: #9bc0ff !important;
  }

  /* GAME CHROME — timer, score, mistakes */

  .game_statistics,
  .game-info-wrapper,
  .timer-wrapper,
  .timer-wrapper_text,
  .score,
  .mistakes-counter,
  .game_statistics_goal_value {
    color: #c4cdd6 !important;
  }

  .game-info-wrapper .score > span,
  .game-info-wrapper .mistakes-counter > span,
  .score-value {
    color: #e6edf3 !important;
  }

  .timer-pause {
    background-color: #242b33 !important;
  }

  .timer-pause:hover {
    background-color: #2e3641 !important;
  }

  .timer-pause:active {
    background-color: #39424f !important;
  }

  /* ACTION CIRCLES — undo, erase, pencil, hint */

  .game-controls .game-controls-item {
    background-color: #242b33 !important;
    border-color: #2d333b !important;
  }

  .game-controls .game-controls-item:hover,
  .mobile .game-controls .game-controls-item:hover {
    background-color: #2e3641 !important;
  }

  .game-controls .game-controls-item:active {
    background-color: #39424f !important;
  }

  /* The four glyphs are an icon font, so they take `color`. */
  .game-controls .icon-game-control {
    color: #c4cdd6 !important;
  }

  .game-controls .game-controls-label {
    color: #9bc0ff !important;
  }

  /* Pencil mode is signalled by the ring, not by the fill. */
  .pencil-mode:not(.win):not(.show-new-pause) .game-controls .game-controls-pencil {
    background-color: #242b33 !important;
    border-color: #7ea2ea !important;
  }

  /* The ON/OFF pill is a ::after; grey means off, brand blue means on. */
  .game-controls .game-controls-pencil:after,
  .new-breakpoints .game-controls .game-controls-item-wrap .game-controls-item.game-controls-pencil:after,
  .portrait .game-controls .game-controls-item-wrap .game-controls-item.game-controls-pencil:after {
    background-color: #4a5462 !important;
    color: #e6edf3 !important;
  }

  .pencil-mode .game-controls .game-controls-pencil:after,
  .new-breakpoints .pencil-mode .game-controls .game-controls-item-wrap .game-controls-item.game-controls-pencil:after,
  .portrait .pencil-mode .game-controls .game-controls-item-wrap .game-controls-item.game-controls-pencil:after {
    background-color: #325aaf !important;
    color: #ffffff !important;
  }

  .game-controls-item .badge,
  .game-controls_hint-count,
  .game-controls-hint-label {
    color: #ffffff !important;
  }

  /* NUMBER PAD */

  .numpad-wrapper .numpad-item,
  .landscape .numpad-wrapper .numpad-item,
  .new-breakpoints .numpad-wrapper .numpad-item {
    background-color: #242b33 !important;
    color: #7ea2ea !important;
  }

  .numpad-wrapper .numpad-item[disabled],
  .landscape .numpad-wrapper .numpad-item[disabled],
  .new-breakpoints .numpad-wrapper .numpad-item[disabled] {
    background-color: #1c2128 !important;
    color: #5b6572 !important;
  }

  .numpad-wrapper .numpad-item:hover,
  .landscape .numpad-wrapper .numpad-item:hover,
  .new-breakpoints .numpad-wrapper .numpad-item:hover {
    background-color: #2e3641 !important;
  }

  .numpad-wrapper .numpad-item:active,
  .landscape .numpad-wrapper .numpad-item:active,
  .new-breakpoints .numpad-wrapper .numpad-item:active {
    background-color: #39424f !important;
  }

  /* NEW GAME BUTTON + DIFFICULTY MENU */

  .difficulty-menu,
  .new-game-menu,
  .difficulty-menu .tooltip-arrow:after,
  .new-game-menu .tooltip-arrow:after,
  .cheats-menu,
  .split-tab,
  .scoreHint,
  .inter-animation_tooltip {
    background-color: #1c2128 !important;
    color: #c4cdd6 !important;
  }

  .new-game-menu-difficulty-block,
  .new-game-menu-mode-button.active,
  .ref-start-game_items > a.selected {
    background-color: #22272e !important;
  }

  .new-game-menu-mode-button,
  .new-game-menu-mode-button.postcard-default,
  .new-game-menu-mode-button.storybook-default {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
    color: #c4cdd6 !important;
  }

  .new-game-menu-mode-button:hover {
    background-color: #22272e !important;
    border-color: #3a424c !important;
  }

  .new-game-menu-header,
  .new-game-menu-button,
  .ref-start-game_items > a {
    color: #c4cdd6 !important;
  }

  .new-game-menu-button {
    border-top-color: #2d333b !important;
  }

  .new-game-menu-button:hover,
  .ref-start-game_items > a:hover {
    background-color: #22272e !important;
  }

  .ref-start-game_items > a:active {
    background-color: #2e3641 !important;
  }

  .new-game-menu-button.active,
  .new-game-menu-mode-button.active,
  .ref-start-game_items > a.active {
    color: #9bc0ff !important;
  }

  /* PAUSE / WIN / GAME OVER / LOST PROGRESS */

  .new-pause,
  .lost-progress,
  .game-over_body,
  .game_settings_body,
  .load-dialog,
  .dc_cnt,
  .build-version {
    background-color: #1c2128 !important;
    color: #c4cdd6 !important;
  }

  .new-pause_title,
  .lost-progress_title,
  .game-over_title,
  .load-dialog-heading,
  .game_settings_header_title,
  .game_settings_content_item_title {
    color: #e6edf3 !important;
  }

  .game_settings_content_item {
    background-color: #22272e !important;
  }

  .game-over_cancel,
  .load-dialog-cancel {
    background-color: #22272e !important;
    color: #9bc0ff !important;
  }

  .game-over,
  .postcards-popup,
  .storybook-popup {
    background-color: rgba(0, 0, 0, 0.72) !important;
  }

  .lose-notification,
  .daily-win-button {
    background-color: #1c2128 !important;
    color: #9bc0ff !important;
  }

  .daily-win-button:hover {
    background-color: #242b33 !important;
  }

  /* SMART HINT CAROUSEL */

  .smart-hint_carousel,
  body.device-desktop.show-smart-hint .game-controls-wrapper.show-smart-hint-carousel,
  body.device-tablet.show-smart-hint .game-controls-wrapper.show-smart-hint-carousel {
    background-color: #1c2128 !important;
  }

  .smart-hint_carousel_name {
    color: #e6edf3 !important;
  }

  .smart-hint_carousel_desc {
    color: #a5b0bd !important;
  }

  .smart-hint_carousel_desc_item span {
    color: #9bc0ff !important;
  }

  .smart-hint_carousel_nav .sh-nav-button,
  .smart-hint_carousel_nav .sh-nav-submit,
  .carousel-nav {
    background-color: #242b33 !important;
  }

  .smart-hint_carousel_nav .sh-nav-button:hover,
  .smart-hint_carousel_nav .sh-nav-submit:hover,
  .carousel-nav:hover {
    background-color: #2e3641 !important;
  }

  .smart-hint_carousel_nav .sh-nav-button:active,
  .smart-hint_carousel_nav .sh-nav-submit:active,
  .carousel-nav:active {
    background-color: #39424f !important;
  }

  /* ARTICLE / TIPS CONTENT */

  .entry-content,
  .entry-content p,
  .entry-content li,
  .entry-content td,
  .entry-content th,
  #tips-articles-wrap,
  .site-content,
  .page-content {
    color: #c4cdd6 !important;
  }

  .entry-content h1,
  .entry-content h2,
  .entry-content h3,
  .entry-content h4,
  .entry-title,
  .entry-title a,
  .daily .entry-content h1,
  .daily .entry-content h2,
  .daily .entry-content h1 a,
  .daily .entry-content h2 a,
  .main-page .entry-content h1,
  .main-page .entry-content h2,
  .main-page .entry-content h3,
  .single-article-page .entry-content h3,
  .articles-page .list-title,
  .page-header_title,
  .calendar-header,
  .rules_header_title,
  .rules_item_title,
  .heading-404 {
    color: #e6edf3 !important;
  }

  .entry-content a,
  .cookies-popup a,
  .more-link,
  .post-navigation-item a,
  .post-navigation a {
    color: #7ea2ea !important;
  }

  .entry-content a:hover,
  .more-link:hover,
  .post-navigation a:hover {
    color: #9bc0ff !important;
  }

  .entry-content ul,
  .page-header_menu {
    background-color: #1a1f26 !important;
    border-color: #2d333b !important;
  }

  .entry-content table,
  .entry-content table td,
  .entry-content table th {
    border-color: #2d333b !important;
  }

  .page-numbers {
    color: #c4cdd6 !important;
  }

  .page-numbers:hover {
    background-color: #22272e !important;
  }

  .page-numbers:hover circle {
    fill: #22272e !important;
  }

  /* ASIDE — app teaser */

  .app-teaser-wrapper {
    background-color: #1a1f26 !important;
  }

  .app-teaser-info {
    background-color: #22272e !important;
    color: #c4cdd6 !important;
  }

  .app-info-heading {
    color: #e6edf3 !important;
  }

  .app-info-author,
  .app-teaser-info {
    color: #8b949e !important;
  }

  /* Badge links wrap an image only; the UA visited colour would leak. */
  .app-teaser-button,
  .app-teaser-button:visited {
    color: #c4cdd6 !important;
  }

  .ios-smart .app-button,
  .mobile-smart .app-info-heading {
    color: #9bc0ff !important;
  }

  /* FOOTER — already dark; deepened to match the page */

  .ref-footer,
  .ref-footer_top,
  .ref-footer_bottom {
    background-color: #0d1117 !important;
  }

  .ref-footer,
  .ref-footer_bottom {
    color: #8b949e !important;
  }

  .ref-footer a {
    color: #c4cdd6 !important;
  }

  .ref-footer a:hover {
    color: #9bd4ff !important;
  }

  .footer-anchor {
    background-color: #22272e !important;
  }

  .footer-anchor:after,
  .footer-anchor:before {
    background-color: #c4cdd6 !important;
  }

  /* CONSENT BANNER + PRIVACY POPUP */

  .cookies-banner,
  .cookies-popup .popup-content,
  .cookies-popup .options-list,
  .cookies-popup .options-dropdown select {
    background-color: #1c2128 !important;
    color: #c4cdd6 !important;
  }

  .cookies-popup .options-list li.active {
    background-color: #22272e !important;
    color: #9bc0ff !important;
  }

  .cookies-popup .options-content > div > div {
    color: #e6edf3 !important;
  }

  .cookies-banner a,
  .cookies-banner span.cookie-settings-link,
  .cookies-btn-link,
  .ot-sdk-show-settings {
    color: #7ea2ea !important;
  }

  .cookies-popup .popup-content__top,
  .cookies-popup .popup-content__bottom {
    border-color: #2d333b !important;
  }

  /* ONETRUST PREFERENCE CENTRE
     
     A page state of its own, reached from the footer after the banner
     is accepted. Its close/expand glyphs are dark PNGs, which only a
     filter can reach. */

  #onetrust-banner-sdk,
  #onetrust-pc-sdk,
  #onetrust-pc-sdk .ot-pc-footer,
  #onetrust-pc-sdk #ot-pc-content,
  #onetrust-pc-sdk .ot-accordion-layout,
  #onetrust-pc-sdk #ot-sel-blk,
  #onetrust-pc-sdk .ot-acc-hdr,
  #onetrust-pc-sdk #ot-fltr-cnt,
  #onetrust-pc-sdk .ot-pc-header {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }

  #onetrust-policy-text,
  #onetrust-policy-text *,
  #ot-pc-title,
  #ot-pc-desc,
  #ot-pc-desc *,
  #onetrust-pc-sdk .ot-acc-txt,
  #onetrust-pc-sdk .ot-acc-txt *,
  #onetrust-pc-sdk h3,
  #onetrust-pc-sdk h4,
  #onetrust-pc-sdk h5,
  #onetrust-pc-sdk p,
  #onetrust-pc-sdk span,
  #onetrust-pc-sdk .ot-always-active,
  #onetrust-pc-sdk #ot-filter-list-header,
  #onetrust-pc-sdk .ot-accordion-layout button {
    color: #c4cdd6 !important;
  }

  body #onetrust-consent-sdk #onetrust-banner-sdk a[href],
  body #onetrust-consent-sdk #onetrust-pc-sdk a[href],
  body #onetrust-consent-sdk #onetrust-pc-sdk .ot-link-btn,
  body #onetrust-consent-sdk #onetrust-pc-sdk .privacy-notice-link,
  #onetrust-pc-sdk #clear-filters-handler {
