  .icon-pause:after {
    background-color: #a8b2bd !important;
  }

  /* State lives in the knob as well as the track: grey knob off,
     brand blue knob on. */
  .game_settings_toggle {
    background-color: rgba(148, 163, 183, 0.28) !important;
  }

  .game_settings_toggle:before {
    background-color: #8b949e !important;
  }

  .active-toggle .game_settings_toggle {
    background-color: rgba(126, 162, 234, 0.3) !important;
  }

  .active-toggle .game_settings_toggle:before {
    background-color: #7ea2ea !important;
  }

