  .printable_body .checkbox .checkbox-icon,
  .checkbox .checkbox-icon {
    background-color: #22272e !important;
  }

  .checkbox .checkbox-icon {
    border-color: #4a5462 !important;
  }

  .checkbox input:checked + .checkbox-icon {
    border-color: #7ea2ea !important;
  }

